/* Cohesive 4-color palette: 
   #2d1b2d (deep plum), #5c3c5e (muted purple), #f8e3c8 (warm cream), #58a36c (matcha green)
*/
:root {
  --bg-color: #2d1b2d;
  --card-bg: #402842;
  --card-border: #1a0f1b;
  --text-main: #f8e3c8;
  --text-muted: #d9bfab;
  --accent: #58a36c;
  --accent-active: #417e52;
  --btn-bg: #5c3c5e;
  --btn-border-light: #7b537d;
  --btn-border-dark: #271428;
  --font-stack: "Courier New", Courier, monospace, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  background-image: 
    linear-gradient(45deg, #241424 25%, transparent 25%),
    linear-gradient(-45deg, #241424 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #241424 75%),
    linear-gradient(-45deg, transparent 75%, #241424 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0px;
  color: var(--text-main);
  font-family: var(--font-stack);
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.app-container {
  width: 100%;
  max-width: 440px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--card-border);
  box-shadow: 6px 6px 0px #120913;
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.card-header {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.pixel-art canvas {
  image-rendering: pixelated;
  width: 64px;
  height: 64px;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--text-main);
}

.preset-group {
  border: none;
  padding: 0;
}

.section-label {
  font-size: 1rem;
  font-weight: bold;
  margin-bottom: 8px;
  text-align: center;
  display: block;
  color: var(--text-muted);
}

.tea-options {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.pixel-btn {
  font-family: var(--font-stack);
  font-size: 1rem;
  font-weight: bold;
  color: var(--text-main);
  background: var(--btn-bg);
  border: 4px solid var(--card-border);
  box-shadow: inset 2px 2px 0px var(--btn-border-light), inset -2px -2px 0px var(--btn-border-dark);
  padding: 10px 6px;
  cursor: pointer;
  outline: none;
  user-select: none;
  text-align: center;
}

.pixel-btn:hover:not(:disabled) {
  filter: brightness(1.15);
}

.pixel-btn:focus-visible {
  outline: 3px dashed var(--accent);
  outline-offset: 2px;
}

.pixel-btn:active:not(:disabled),
.pixel-btn.is-selected {
  background: var(--accent);
  box-shadow: inset 2px 2px 0px var(--accent-active), inset -2px -2px 0px #7fd095;
  transform: translateY(2px);
}

.pixel-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  filter: grayscale(0.5);
}

.tea-btn .subtext {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.tea-btn.is-selected .subtext {
  color: #122818;
}

.display-panel {
  background: #1a0f1b;
  border: 4px solid #100811;
  padding: 16px;
  text-align: center;
  box-shadow: inset 2px 2px 6px rgba(0, 0, 0, 0.6);
}

.tea-indicator {
  font-size: 1rem;
  color: var(--text-muted);
  margin-bottom: 6px;
}

.time-digits {
  font-size: 3rem;
  font-weight: bold;
  letter-spacing: 3px;
  color: var(--text-main);
}

.status-message {
  margin-top: 10px;
  color: var(--accent);
  font-size: 1.15rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  animation: blink 1s steps(2, start) infinite;
}

@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

.action-controls {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.primary-btn {
  background: var(--accent);
  color: #0f2414;
  box-shadow: inset 2px 2px 0px #7fd095, inset -2px -2px 0px var(--accent-active);
}

.secondary-btn {
  background: #6a3644;
  box-shadow: inset 2px 2px 0px #8e495b, inset -2px -2px 0px #421d28;
}

@media (max-width: 380px) {
  .tea-options {
    grid-template-columns: 1fr;
  }
  .time-digits {
    font-size: 2.4rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const teaButtons = document.querySelectorAll('.tea-btn');
  const startBtn = document.getElementById('start-btn');
  const cancelBtn = document.getElementById('cancel-btn');
  const timerDisplay = document.getElementById('timer-display');
  const selectedTeaLabel = document.getElementById('selected-tea-label');
  const readyMessage = document.getElementById('ready-message');
  const canvas = document.getElementById('tea-canvas');

  let selectedTea = 'Green';
  let presetSeconds = 120;
  let remainingSeconds = 120;
  let timerInterval = null;
  let isRunning = false;

  // Draw pixel teacup on canvas
  function drawPixelTeacup() {
    if (!canvas || !canvas.getContext) return;
    const ctx = canvas.getContext('2d');
    const p = 4; // pixel size
    ctx.clearRect(0, 0, 64, 64);

    const cupMap = [
      '        ....    ',
      '    .  .    .   ',
      '     .      .   ',
      '  ..........    ',
      '  .########.    ',
      '  .########.... ',
      '  .########.  . ',
      '  .########.  . ',
      '   .######..... ',
      '    .####.      ',
      '   ........     '
    ];

    for (let r = 0; r < cupMap.length; r++) {
      for (let c = 0; c < cupMap[r].length; c++) {
        const ch = cupMap[r][c];
        if (ch === '.') {
          ctx.fillStyle = '#1a0f1b';
          ctx.fillRect(c * p, r * p + 8, p, p);
        } else if (ch === '#') {
          ctx.fillStyle = isRunning ? '#58a36c' : '#f8e3c8';
          ctx.fillRect(c * p, r * p + 8, p, p);
        }
      }
    }
  }

  function formatTime(totalSeconds) {
    const m = Math.floor(totalSeconds / 60);
    const s = totalSeconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  }

  function updateDisplay() {
    timerDisplay.textContent = formatTime(remainingSeconds);
  }

  function selectPreset(button) {
    if (isRunning) return;
    teaButtons.forEach(btn => {
      btn.classList.remove('is-selected');
      btn.setAttribute('aria-pressed', 'false');
    });
    button.classList.add('is-selected');
    button.setAttribute('aria-pressed', 'true');

    selectedTea = button.getAttribute('data-tea');
    presetSeconds = parseInt(button.getAttribute('data-seconds'), 10);
    remainingSeconds = presetSeconds;
    selectedTeaLabel.textContent = `Selected: ${selectedTea} Tea`;
    readyMessage.hidden = true;
    updateDisplay();
  }

  function startTimer() {
    if (isRunning) return;
    isRunning = true;
    readyMessage.hidden = true;

    startBtn.disabled = true;
    cancelBtn.disabled = false;
    teaButtons.forEach(btn => (btn.disabled = true));
    drawPixelTeacup();

    const targetTimestamp = Date.now() + remainingSeconds * 1000;

    timerInterval = setInterval(() => {
      const now = Date.now();
      const diffSeconds = Math.max(0, Math.ceil((targetTimestamp - now) / 1000));
      remainingSeconds = diffSeconds;
      updateDisplay();

      if (remainingSeconds <= 0) {
        clearInterval(timerInterval);
        timerInterval = null;
        isRunning = false;
        readyMessage.hidden = false;
        startBtn.disabled = false;
        cancelBtn.disabled = true;
        teaButtons.forEach(btn => (btn.disabled = false));
        drawPixelTeacup();
      }
    }, 250);
  }

  function cancelTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    isRunning = false;
    remainingSeconds = presetSeconds;
    updateDisplay();
    readyMessage.hidden = true;

    startBtn.disabled = false;
    cancelBtn.disabled = true;
    teaButtons.forEach(btn => (btn.disabled = false));
    drawPixelTeacup();
  }

  teaButtons.forEach(btn => {
    btn.addEventListener('click', () => selectPreset(btn));
  });

  startBtn.addEventListener('click', startTimer);
  cancelBtn.addEventListener('click', cancelTimer);

  updateDisplay();
  drawPixelTeacup();
});
